import sanitizeHtml from 'sanitize-html';

/**
 * Cleans blog HTML before it is shown on the public site.
 *
 * Blog posts are HTML written in the admin editor (TipTap) or generated by AI. Rendering it
 * as-is would let any <script>, onerror="..." handler or javascript: link inside it run in
 * visitors' browsers (XSS). This keeps only the formatting the editor can actually produce
 * (headings, text styles, lists, quotes, code, links, images, tables) and drops everything else.
 */
const ALLOWED_TAGS = [
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
  'p', 'br', 'hr', 'blockquote', 'pre', 'code',
  'strong', 'b', 'em', 'i', 'u', 's', 'mark', 'sub', 'sup', 'span', 'div',
  'ul', 'ol', 'li',
  'a', 'img', 'figure', 'figcaption',
  'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td', 'caption', 'colgroup', 'col',
];

export function sanitizeBlogHtml(dirty: string | null | undefined): string {
  if (!dirty) return '';

  return sanitizeHtml(dirty, {
    allowedTags: ALLOWED_TAGS,
    allowedAttributes: {
      a: ['href', 'name', 'target', 'rel', 'title'],
      img: ['src', 'alt', 'title', 'width', 'height', 'loading'],
      th: ['colspan', 'rowspan', 'colwidth', 'data-colwidth'],
      td: ['colspan', 'rowspan', 'colwidth', 'data-colwidth'],
      col: ['span', 'style'],
      colgroup: ['span'],
      '*': ['class', 'id'],
    },
    // Only safe link types; no javascript: / data: URLs.
    allowedSchemes: ['http', 'https', 'mailto', 'tel'],
    allowedSchemesByTag: { img: ['http', 'https'] },
    allowProtocolRelative: false,
    // Table column widths from the editor.
    allowedStyles: {
      col: { width: [/^\d+(?:\.\d+)?(?:px|%)$/], 'min-width': [/^\d+(?:\.\d+)?(?:px|%)$/] },
    },
    transformTags: {
      // Links that open a new tab must not give the new page access to ours.
      a: (tagName, attribs) => {
        if (attribs.target === '_blank') {
          return { tagName, attribs: { ...attribs, rel: 'noopener noreferrer' } };
        }
        return { tagName, attribs };
      },
    },
  });
}
